import { MakeLogicType, afterMount, connect, kea, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { projectLogic } from 'scenes/projectLogic'

import { tasksModelsRetrieve } from 'products/tasks/frontend/generated/api'
import { ModelChoiceApi } from 'products/tasks/frontend/generated/api.schemas'

import { FALLBACK_MODEL_CHOICES } from '../utils/composerModels'

const CATALOGUE_STORAGE_KEY = 'posthog_ai_model_catalogue'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface modelCatalogueLogicValues {
    currentProjectId: number | null // projectLogic
    cachedCatalogue: ModelChoiceApi[] | null
    catalogue: ModelChoiceApi[]
    fetchedCatalogue: ModelChoiceApi[] | null
    fetchedCatalogueLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface modelCatalogueLogicActions {
    loadCatalogue: () => any
    loadCatalogueFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadCatalogueSuccess: (
        fetchedCatalogue: ModelChoiceApi[] | null,
        payload?: any
    ) => {
        fetchedCatalogue: ModelChoiceApi[] | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface modelCatalogueLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        catalogue: (
            fetchedCatalogue: ModelChoiceApi[] | null,
            cachedCatalogue: ModelChoiceApi[] | null
        ) => ModelChoiceApi[]
    }
}

export type modelCatalogueLogicType = MakeLogicType<
    modelCatalogueLogicValues,
    modelCatalogueLogicActions,
    Record<string, any>,
    modelCatalogueLogicMeta
>

/**
 * The models a task run may use, fetched from the tasks API rather than hardcoded — the endpoint derives it from the
 * live LLM gateway catalogue, so a newly released model reaches the composer without a frontend change.
 *
 * Served stale-while-revalidate: the last catalogue seen is kept in local storage and rendered immediately, while a
 * fresh one is fetched in the background. Whatever the fetch can't answer — no project, an unreachable gateway (the
 * endpoint answers with an empty list), a failed request — leaves the last known catalogue in place, and a small
 * built-in list stands in until there is one, so the model dropdown is never empty and never briefly loses the models
 * it showed a moment ago.
 */
export const modelCatalogueLogic = kea<modelCatalogueLogicType>([
    path(['products', 'posthog_ai', 'frontend', 'logics', 'modelCatalogueLogic']),

    connect(() => ({
        values: [projectLogic, ['currentProjectId']],
    })),

    loaders(({ values }) => ({
        fetchedCatalogue: [
            null as ModelChoiceApi[] | null,
            {
                loadCatalogue: async (): Promise<ModelChoiceApi[] | null> => {
                    if (values.currentProjectId == null) {
                        return null
                    }
                    try {
                        const response = await tasksModelsRetrieve(String(values.currentProjectId))
                        // An empty list means the gateway is unreachable, not that no model exists.
                        return response.models.length ? response.models : null
                    } catch {
                        return null
                    }
                },
            },
        ],
    })),

    reducers({
        cachedCatalogue: [
            null as ModelChoiceApi[] | null,
            { persist: true, storageKey: CATALOGUE_STORAGE_KEY },
            {
                loadCatalogueSuccess: (state, { fetchedCatalogue }) => fetchedCatalogue ?? state,
            },
        ],
    }),

    selectors({
        catalogue: [
            (s) => [s.fetchedCatalogue, s.cachedCatalogue],
            (fetched: ModelChoiceApi[] | null, cached: ModelChoiceApi[] | null): ModelChoiceApi[] =>
                fetched ?? cached ?? FALLBACK_MODEL_CHOICES,
        ],
    }),

    afterMount(({ actions }) => {
        actions.loadCatalogue()
    }),
])
